//! 🧪️ Scratch laws share one genuine caller, exact one-fuel frames and complete physical closure.
use semio_framework_job::{OriginalJobFixtureCaller,OriginalJobDecodeOwner,StepContext,OriginalTurnFailure,OperationId,Generation,close_original_retained_step};
use semio_framework_value::{RetainedCloneGrant,RetainedCloneProgress,RetainedWorkOutcome};
use semio_framework_value::retirement::{RetireOwned,controlled::ControlledRetirement};
pub(crate) fn clock()->Option<u64>{Some(1000)}
fn delta(a:RetainedCloneProgress,b:RetainedCloneProgress)->RetainedCloneProgress{RetainedCloneProgress{copied_items:b.copied_items-a.copied_items,copied_bytes:b.copied_bytes-a.copied_bytes,retained_capacity_bytes:b.retained_capacity_bytes-a.retained_capacity_bytes,released_bytes:b.released_bytes-a.released_bytes}}
pub(crate) struct ScratchCaller{pub calls:usize,caller:OriginalJobFixtureCaller,decoder:OriginalJobDecodeOwner,stock:RetainedCloneGrant,loan:RetainedCloneGrant,born:usize,released:usize,maximum_work:u64}
impl ScratchCaller{
 pub fn new(policy:&serde_json::Value,items:usize,seed_bytes:usize)->Self{let stock:RetainedCloneGrant=serde_json::from_value(policy["grant"].clone()).unwrap();let caller=OriginalJobFixtureCaller::admit(OperationId(policy["operation"].as_u64().unwrap()),Generation(policy["generation"].as_u64().unwrap()),stock,clock,policy["deadlineUs"].as_u64().unwrap(),policy["fuel"].as_u64().unwrap());let born=caller.born_bytes()+seed_bytes;Self{calls:0,caller,decoder:OriginalJobDecodeOwner::empty(),stock,loan:RetainedCloneGrant{maximum_items:items.min(stock.maximum_items),..stock},born,released:0,maximum_work:0}}
 pub fn turn<R>(&mut self,run:impl FnOnce(&mut StepContext<'_>)->Result<R,OriginalTurnFailure>)->R{
  self.calls+=1;let fuel=self.caller.fuel_remaining();let mut physical=(0,0);let mut answer=None;self.caller.turn_with_decoder(self.loan,&mut self.decoder,|cx|{let deadline=cx.original_absolute_deadline_us();cx.with_original_work_loan(1,deadline,|same|{
   let before=same.retained_progress();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||run(same));let p=delta(before,same.retained_progress());assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));physical=(heap.requested_bytes,heap.released_bytes);answer=Some(result?);Ok(())
  })}).unwrap();self.born+=physical.0;self.released+=physical.1;self.maximum_work=self.maximum_work.max(fuel-self.caller.fuel_remaining());answer.expect("original scratch callback produced its owned result")
 }
 pub fn cancel(&self){self.caller.cancel().cancel_now()}
 pub fn close<T:RetireOwned>(&mut self,value:T){let mut owner=ControlledRetirement::new(value).unwrap_or_else(|_|panic!("scratch fixture owner has controlled retirement"));for _ in 0..32768{if owner.terminal_is_empty(){return}self.turn(|cx|cx.with_original_retirement(|same|{let d=owner.selected_demand(same.retained_grant().maximum_copy_bytes)?;close_original_retained_step(same,d,|g|{let result=owner.step(g);RetainedWorkOutcome{result,work:owner.last_turn_work()}})?;Ok(())}));}panic!("scratch owner failed to reach physical terminal")}
 pub fn finish(mut self)->usize{
  for _ in 0..32768{if self.decoder.terminal_is_empty(){break}self.calls+=1;let fuel=self.caller.fuel_remaining();let mut physical=(0,0);self.caller.turn(self.loan,|cx|{let deadline=cx.original_absolute_deadline_us();cx.with_original_work_loan(1,deadline,|same|same.with_original_retirement(|same|{let before=same.retained_progress();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{let d=self.decoder.retirement_demands(same.retained_grant().maximum_copy_bytes)?;close_original_retained_step(same,d,|g|self.decoder.close_step(g))?;Ok(())});let p=delta(before,same.retained_progress());assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));physical=(heap.requested_bytes,heap.released_bytes);result}))}).unwrap();self.born+=physical.0;self.released+=physical.1;self.maximum_work=self.maximum_work.max(fuel-self.caller.fuel_remaining());}
  assert!(self.decoder.terminal_is_empty());for _ in 0..64{if self.caller.terminal_is_empty(){break}self.calls+=1;let d=self.caller.retirement_demands().unwrap();let fuel=self.caller.fuel_remaining();let step=self.caller.retire_step(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}).unwrap();let p=step.progress();self.born+=p.retained_capacity_bytes;self.released+=p.released_bytes;self.maximum_work=self.maximum_work.max(fuel-self.caller.fuel_remaining());}
  assert!(self.caller.terminal_is_empty());assert_eq!(self.caller.stock(),self.stock);assert!(self.caller.cumulative_receipt().fits(self.stock));assert_eq!(self.born,self.released);assert!(self.maximum_work<=1,"scratch event exceeded its actual one-fuel caller frame");assert!(self.calls<=200,"whole scratch fixture used {} original one-fuel calls",self.calls);self.calls
 }
}
impl Drop for ScratchCaller{fn drop(&mut self){assert!(self.caller.terminal_is_empty()&&self.decoder.terminal_is_empty(),"scratch law retains original caller or decoder")}}
